 if(!env.OWNER_CODE||request.headers.get('authorization')!=='Bearer '+env.OWNER_CODE)return new Response('Incorrect owner access code.',{status:403});
 let body;try{body=await request.json()}catch{return new Response('Invalid settings.',{status:400})}
